REVOKE EXECUTE ON FUNCTION public.has_role(uuid, public.app_role), public.my_hotel(), public.is_member(), public.can_hotel(uuid), public.is_mgr(uuid), public.guest_visits(uuid), public.run_backup(), public.handle_new_user() FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.handle_new_user() FROM authenticated;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role), public.my_hotel(), public.is_member(), public.can_hotel(uuid), public.is_mgr(uuid), public.guest_visits(uuid), public.run_backup() TO authenticated;
SELECT cron.schedule('nightly-backup', '30 20 * * *', $$SELECT public.run_backup();$$);